:root{
    --sky1:#7ed4ff;
    --sky2:#dff6ff;
    --panel:#fff6dd;
    --panel-border:#5a2b14;
    --red:#e53d2e;
    --yellow:#ffd84d;
    --green:#17a83d;
    --shadow:0 8px 0 rgba(0,0,0,.18), 0 14px 26px rgba(0,0,0,.18);
  }
  *{box-sizing:border-box}
  body{
    margin:0;
    font-family:"Nunito", Arial, Helvetica, sans-serif;
    color:#2f190a;
    background:linear-gradient(to bottom,#69cfff 0%,#bdeaff 48%,#e9fbff 67%,#7bd96b 67%,#63c451 100%);
    min-height:100vh;
    overflow-x:hidden;
    position:relative;
  }
  .titlebar,.hud,.wrap{position:relative;z-index:5}
  .titlebar{padding:16px 18px 8px;text-align:center}
  .logo{
    display:inline-block;padding:12px 24px;border:4px solid #4e2008;border-radius:18px;
    background:linear-gradient(#fff8e9,#ffd797);box-shadow:var(--shadow);
    font-size:clamp(1.2rem,3vw,2.2rem);font-weight:900;letter-spacing:.04em;text-transform:uppercase;
  }
  .logo .red{color:var(--red)} .logo .green{color:var(--green)} .logo .yellow{color:#c98b00}
  .hud{max-width:1320px;margin:10px auto 0;padding:0 14px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
  .hud-card,.panel{background:linear-gradient(180deg,rgba(255,249,225,.96),rgba(255,235,185,.94));border:4px solid var(--panel-border);box-shadow:0 9px 0 rgba(92,47,19,.17),0 18px 38px rgba(35,73,99,.16);backdrop-filter:blur(3px)}
  .hud-card{border-radius:18px;padding:12px 14px}
  .hud-card h3{margin:0 0 6px;font-size:.9rem;text-transform:uppercase;letter-spacing:.08em}
  .big{font-size:1.35rem;font-weight:900}
  .wrap{width:100%;max-width:1560px;margin:18px auto 34px;padding:0 14px 28px;display:grid;grid-template-columns:minmax(190px,240px) minmax(0,1fr) minmax(190px,240px);gap:16px;align-items:start}
  .panel{border-radius:22px;overflow:hidden}
  .panel .panel-head{padding:14px 16px;background:linear-gradient(to bottom, #ffe89e, #ffd255);border-bottom:4px solid var(--panel-border);font-weight:900;text-transform:uppercase;letter-spacing:.06em}
  .panel .section{padding:14px 16px;border-top:2px dashed rgba(90,43,20,.22)}
  .panel .section:first-child{border-top:0}
  .player-card{display:flex;align-items:center;gap:12px}
  .avatar{width:72px;height:72px;border-radius:18px;border:4px solid #4b230e;display:grid;place-items:center;background:linear-gradient(#fff3c5,#ffd34d);box-shadow:0 5px 0 rgba(0,0,0,.14);overflow:hidden;padding:4px}.avatar img{width:100%;height:100%;object-fit:contain;display:block}
  .player-card strong{display:block;font-size:1.1rem}
  .sub{opacity:.8;font-size:.92rem}
  .captured{min-height:54px;display:flex;flex-wrap:wrap;gap:7px}
  .cap{width:40px;height:40px;border-radius:10px;border:2px solid #60331a;background:#fff8ea;display:grid;place-items:center;font-size:1.55rem}
  .buttons{display:grid;gap:10px}
  button{border:0;border-radius:14px;padding:12px 14px;font-weight:900;font-size:1rem;cursor:pointer}
  .btn-main{background:linear-gradient(to bottom, #ff6957, #da3728);color:#fff;box-shadow:0 6px 0 #9e261b}
  .btn-yellow{background:linear-gradient(to bottom, #ffe989, #efc02d);color:#4c290d;box-shadow:0 6px 0 #b98911}
  button:active{transform:translateY(3px)}
  .board-shell{min-width:0;width:100%;position:relative;background:linear-gradient(to bottom, #5ad452 0 22px, #2d9e32 22px 28px, #d9773b 28px 100%);border:6px solid #683014;border-radius:26px;box-shadow:var(--shadow);padding:28px 18px 20px;overflow:hidden}
  .board-shell:before{content:"";position:absolute;inset:0 0 auto 0;height:28px;background:linear-gradient(to bottom,#4ed84a,#2ea332)}
  .pipe-left,.pipe-right{position:absolute;bottom:20px;width:55px;height:130px;border-radius:14px 14px 8px 8px;background:linear-gradient(to right,#0f7a28,#27c249 45%,#0d8d30 60%,#0c5d1f);border:4px solid #094c19;box-shadow:inset 0 0 0 4px rgba(255,255,255,.08);z-index:1}
  .pipe-left{left:-6px}.pipe-right{right:-6px}
  .pipe-left:before,.pipe-right:before{content:"";position:absolute;left:50%;transform:translateX(-50%);top:-18px;width:78px;height:24px;border-radius:12px;background:linear-gradient(to right,#0f7a28,#34d759 45%,#0d8d30 60%,#0c5d1f);border:4px solid #094c19}
  .board-area{position:relative;z-index:2;width:min(92%,860px);max-width:100%;margin:0 auto;display:flex;flex-direction:column;justify-content:flex-start;min-width:0}
  .board-topbar{display:flex;justify-content:space-between;gap:10px;align-items:center;margin:0 auto 12px;width:100%;padding:10px 12px;background:#fff6dd;border:4px solid #60331a;border-radius:18px}
  .status{font-weight:900;font-size:1rem}.turn-badge{padding:8px 12px;border-radius:999px;background:#ffe791;border:2px solid #6b340f;font-weight:900}
  .board{position:relative;display:grid;grid-template-columns:repeat(8,minmax(0,1fr));grid-template-rows:repeat(8,minmax(0,1fr));width:100%;max-width:100%;aspect-ratio:1/1;border:8px solid #6b340f;border-radius:10px;overflow:hidden;background:#5c300f;flex:0 0 auto}
  .sq{position:relative;display:flex;align-items:center;justify-content:center;min-width:0;min-height:0;overflow:hidden;user-select:none;cursor:pointer;padding:3px}
  .light{background:#f7efdb}.dark{background:#b26b3f}
  .sq.selected{box-shadow:inset 0 0 0 5px rgba(255,226,84,.98)}
  .sq.last{box-shadow:inset 0 0 0 999px rgba(88,198,255,.18)}
  .sq.check{box-shadow:inset 0 0 0 999px rgba(255,66,66,.26)}
  .coord{position:absolute;font-size:10px;font-weight:900;opacity:.75;text-shadow:0 1px 0 rgba(255,255,255,.45);pointer-events:none}
  .file{right:4px;bottom:3px}.rank{left:4px;top:3px}
  
  .piece{position:relative;z-index:3;display:flex;align-items:center;justify-content:center;width:92%;height:92%;padding:3px;border-radius:10px;border:2px solid rgba(0,0,0,.18);filter:drop-shadow(0 3px 2px rgba(0,0,0,.18));text-align:center;line-height:1;overflow:hidden}
  .piece.white{background:linear-gradient(#fff9eb,#ffe090);color:#57250a}
  .piece.black{background:linear-gradient(#6e3a1b,#40200d);color:#fff3d8}
  .piece-img{display:block;width:100%;height:100%;max-width:100%;max-height:100%;object-fit:contain;pointer-events:none}
  .cap .piece{width:100%;height:100%;padding:2px;border-radius:8px;border-width:1px}
  .cap .piece-img{max-height:100%}

  .dot{position:absolute;width:19%;height:19%;border-radius:999px;background:#24c442;border:2px solid rgba(255,255,255,.7);box-shadow:0 0 14px rgba(36,196,66,.4);z-index:2}
  .ring{position:absolute;inset:12%;border-radius:999px;border:5px solid #24c442;box-shadow:0 0 14px rgba(36,196,66,.4);z-index:2}
  .moves{max-height:220px;overflow:auto;display:grid;gap:8px}
  .move-row{display:grid;grid-template-columns:40px 1fr 1fr;gap:8px;padding:8px 10px;background:#fffdf6;border:2px solid rgba(90,43,20,.15);border-radius:12px;font-size:.95rem}
  .hint-list{display:flex;flex-wrap:wrap;gap:8px}
  .hint-chip{padding:8px 10px;background:#fffdf6;border:2px solid rgba(90,43,20,.18);border-radius:999px;font-weight:800;font-size:.9rem}
  .capture-overlay{position:fixed;pointer-events:none;z-index:9999;width:86px;height:110px}
  .capture-overlay .pipe{position:absolute;left:50%;bottom:0;transform:translateX(-50%);width:62px;height:84px;background:linear-gradient(to right,#0f7a28,#31d454 45%,#0f962f 60%,#0c5d1f);border:4px solid #094c19;border-radius:12px 12px 8px 8px;animation:pipe-rise .7s ease-out forwards;box-shadow:0 8px 12px rgba(0,0,0,.25)}
  .capture-overlay .pipe:before{content:"";position:absolute;left:50%;transform:translateX(-50%);top:-17px;width:82px;height:22px;border-radius:12px;background:linear-gradient(to right,#0f7a28,#3ddd60 45%,#0f962f 60%,#0c5d1f);border:4px solid #094c19}
  .capture-overlay .victim{position:absolute;left:50%;top:0;transform:translateX(-50%);width:64px;height:72px;animation:piece-drop .95s ease-in forwards;filter:drop-shadow(0 4px 6px rgba(0,0,0,.25))}.capture-overlay .victim .piece{width:100%;height:100%;padding:4px;border-radius:12px}.capture-overlay .victim .piece-icon{font-size:1.35rem}.capture-overlay .victim .piece-name{font-size:.55rem}
  .capture-overlay .stars{position:absolute;inset:0}
  .capture-overlay .star{position:absolute;font-size:1.2rem;color:#ffd84d;animation:star-pop 1s ease-out forwards}
  @keyframes pipe-rise{0%{transform:translateX(-50%) translateY(40px) scale(.7);opacity:.1}100%{transform:translateX(-50%) translateY(0) scale(1);opacity:1}}
  @keyframes piece-drop{0%{top:-4px;opacity:1}62%{top:18px;opacity:1}100%{top:58px;opacity:0}}
  @keyframes star-pop{0%{transform:translate(0,0) scale(.2);opacity:0}20%{opacity:1}100%{transform:translate(var(--x), var(--y)) scale(1.4);opacity:0}}
  .footer-note{text-align:center;font-size:.88rem;opacity:.8;margin-top:12px}
  @media (max-width:1260px){.wrap{grid-template-columns:1fr;max-width:940px}.board-area{width:min(94%,820px)}.side,.panel{min-width:0}.hud{grid-template-columns:repeat(2,minmax(0,1fr))}}
  @media (max-width:640px){.wrap{padding-left:8px;padding-right:8px}.board-shell{padding-left:8px;padding-right:8px}.board{border-width:5px}.hud{grid-template-columns:1fr}.board-topbar{flex-direction:column;align-items:flex-start}.piece{font-size:2rem}}

  /* ===== BACKGROUND MARIO ANIME ===== */
  .world-bg{position:fixed;inset:0;z-index:1;pointer-events:none;overflow:hidden}
  .world-sun{position:absolute;right:6vw;top:7vh;width:94px;height:94px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#fff9bb 0 14%,#ffe760 32%,#ffc52b 72%,#f09c00 100%);box-shadow:0 0 45px rgba(255,219,72,.42);animation:sunFloat 5.5s ease-in-out infinite}
  .cloud{position:absolute;width:150px;height:54px;border-radius:999px;background:rgba(255,255,255,.92);filter:drop-shadow(0 7px 8px rgba(66,139,177,.12));opacity:.92;animation:cloudDrift linear infinite}
  .cloud:before,.cloud:after{content:"";position:absolute;background:inherit;border-radius:50%}
  .cloud:before{width:70px;height:70px;left:28px;top:-28px}
  .cloud:after{width:86px;height:86px;right:20px;top:-40px}
  .cloud.c1{top:14%;left:-190px;animation-duration:33s;transform:scale(.85)}
  .cloud.c2{top:30%;left:-230px;animation-duration:45s;animation-delay:-17s;transform:scale(1.1);opacity:.72}
  .cloud.c3{top:8%;left:-170px;animation-duration:39s;animation-delay:-29s;transform:scale(.62);opacity:.78}

  .hill{position:absolute;bottom:0;border-radius:52% 52% 0 0;background:linear-gradient(180deg,#55c950,#2da743);border:4px solid rgba(21,126,48,.22);box-shadow:inset 0 8px 0 rgba(255,255,255,.12)}
  .hill:before,.hill:after{content:"";position:absolute;width:13px;height:21px;border-radius:50%;background:#1d9a39;opacity:.55}
  .hill:before{left:28%;top:32%}.hill:after{right:25%;top:49%}
  .hill.h1{width:310px;height:170px;left:-80px}
  .hill.h2{width:430px;height:215px;right:-125px;background:linear-gradient(180deg,#68dc58,#35ad44)}
  .hill.h3{width:250px;height:130px;left:35%;opacity:.72}

  .bush{position:absolute;bottom:1%;width:120px;height:48px;border-radius:55px 55px 15px 15px;background:#2faf3f;border:4px solid rgba(16,115,39,.28)}
  .bush:before,.bush:after{content:"";position:absolute;border-radius:50%;background:#39bd49}
  .bush:before{width:62px;height:62px;left:6px;top:-27px}.bush:after{width:72px;height:72px;right:4px;top:-34px}
  .bush.b1{left:16%}.bush.b2{right:20%;transform:scale(.8)}

  .question-block{position:absolute;width:48px;height:48px;border:4px solid #8f4f0d;border-radius:7px;background:linear-gradient(145deg,#ffd84e,#f5a617);box-shadow:inset 4px 4px 0 rgba(255,255,255,.3),inset -4px -4px 0 rgba(156,78,5,.2),0 7px 0 rgba(102,53,9,.16);display:grid;place-items:center;color:#fff6b7;font-size:30px;font-weight:1000;text-shadow:2px 2px 0 #b66b00;animation:blockBob 3.2s ease-in-out infinite}
  .question-block.q1{left:4vw;top:39%}.question-block.q2{right:5vw;top:47%;animation-delay:-1.4s;transform:scale(.85)}

  .brick-row{position:absolute;display:flex;gap:10px;opacity:.95;align-items:flex-start}
  .brick-row.r1{left:7vw;top:56%;transform:scale(.86)}.brick-row.r2{right:7vw;top:26%;transform:scale(.72)}
  .brick{width:92px;height:92px;background:url('data:image/png;base64,') center/contain no-repeat;display:block;filter:drop-shadow(0 8px 10px rgba(66,36,17,.18))}
  .brick:after{content:none}

  .coin-bg{position:absolute;width:27px;height:38px;border-radius:50%;background:linear-gradient(90deg,#c98000,#ffe66d 28%,#fff5ae 50%,#ffcb31 73%,#b67200);border:3px solid #b57500;box-shadow:0 0 18px rgba(255,216,64,.42);animation:coinSpin 2.2s linear infinite,coinFloat 3.6s ease-in-out infinite}
  .coin-bg.c1{left:23%;top:18%}.coin-bg.c2{right:26%;top:35%;animation-delay:-.7s}.coin-bg.c3{left:72%;top:11%;animation-delay:-1.4s}.coin-bg.c4{left:11%;top:71%;animation-delay:-2.1s}

  .sparkle{position:absolute;width:8px;height:8px;border-radius:50%;background:#fff7a0;box-shadow:0 0 12px #fff266;animation:spark 2.4s ease-in-out infinite}
  .sparkle.s1{left:30%;top:24%}.sparkle.s2{right:34%;top:19%;animation-delay:-1s}.sparkle.s3{left:60%;top:50%;animation-delay:-1.8s}

  @keyframes cloudDrift{from{left:-230px}to{left:calc(100% + 240px)}}
  @keyframes sunFloat{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-7px) rotate(4deg)}}
  @keyframes blockBob{0%,100%{translate:0 0}50%{translate:0 -8px}}
  @keyframes coinSpin{0%{transform:rotateY(0)}100%{transform:rotateY(360deg)}}
  @keyframes coinFloat{0%,100%{translate:0 0}50%{translate:0 -10px}}
  @keyframes spark{0%,100%{opacity:.15;transform:scale(.5)}50%{opacity:1;transform:scale(1.5)}}

  .logo{position:relative;overflow:hidden}
  .logo:after{content:"";position:absolute;top:-45%;left:-35%;width:26%;height:190%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.55),transparent);transform:rotate(18deg);animation:logoShine 5s ease-in-out infinite}
  @keyframes logoShine{0%,65%{left:-35%}86%,100%{left:125%}}

  .board-shell{box-shadow:0 10px 0 rgba(89,43,17,.24),0 24px 55px rgba(24,81,117,.24),0 0 0 2px rgba(255,255,255,.13) inset !important}
  .board-shell:after{content:"";position:absolute;inset:28px 0 0;pointer-events:none;background:linear-gradient(110deg,transparent 20%,rgba(255,255,255,.07) 38%,transparent 55%);transform:translateX(-120%);animation:boardGlow 8s ease-in-out infinite}
  @keyframes boardGlow{0%,55%{transform:translateX(-120%)}75%,100%{transform:translateX(120%)}}

  @media (prefers-reduced-motion:reduce){
    .cloud,.world-sun,.question-block,.coin-bg,.sparkle,.logo:after,.board-shell:after{animation:none !important}
  }

  /* ===== BACKGROUND RICHE AVEC IMAGES ===== */
  .world-bg{perspective:900px}
  .parallax-back,.parallax-mid,.parallax-front{position:absolute;inset:0;pointer-events:none}
  .parallax-back{z-index:1}
  .parallax-mid{z-index:2}
  .parallax-front{z-index:3}

  .bg-item{position:absolute;display:block;user-select:none;pointer-events:none;transform-origin:center center;will-change:transform,opacity}
  .bg-flower{width:150px;aspect-ratio:1/1;background:url('data:image/png;base64,') center/contain no-repeat;filter:drop-shadow(0 12px 18px rgba(0,0,0,.16));animation:flowerBob 4.2s ease-in-out infinite}
  .bg-flower.f1{left:4vw;bottom:5vh;animation-delay:-.6s;transform:scale(1.05)}
  .bg-flower.f2{right:5vw;bottom:6vh;animation-delay:-2.1s;transform:scale(.95) rotate(-3deg)}
  .bg-flower.f3{left:16vw;bottom:4vh;width:105px;opacity:.86;animation-duration:5.8s;animation-delay:-1.2s}
  .bg-flower.f4{right:18vw;bottom:4vh;width:92px;opacity:.82;animation-duration:5s;animation-delay:-3.2s;transform:rotate(8deg)}

  .bg-qblock{width:88px;aspect-ratio:1/1;background:url('data:image/png;base64,') center/contain no-repeat;filter:drop-shadow(0 10px 14px rgba(0,0,0,.14));animation:qFloat 3.1s ease-in-out infinite}
  .bg-qblock.qb1{left:6vw;top:9vh;animation-delay:-.9s}
  .bg-qblock.qb2{right:7vw;top:12vh;animation-delay:-1.9s;transform:scale(1.08)}
  .bg-qblock.qb3{left:23vw;top:7vh;width:68px;opacity:.88;animation-duration:4.2s;animation-delay:-2.3s}
  .bg-qblock.qb4{right:24vw;top:8vh;width:76px;opacity:.9;animation-duration:3.7s;animation-delay:-.5s}

  .coin-stack{position:absolute;display:flex;gap:8px;align-items:flex-end;opacity:.95}
  .coin-stack.left{left:18vw;bottom:8vh}
  .coin-stack.right{right:17vw;bottom:7vh;transform:scale(.9)}
  .coin-stack span{display:block;width:25px;height:36px;border-radius:50%;background:linear-gradient(90deg,#c98000,#ffe66d 28%,#fff5ae 50%,#ffcb31 73%,#b67200);border:3px solid #b57500;box-shadow:0 0 18px rgba(255,216,64,.36);animation:coinSpin 2.2s linear infinite,coinBounce 2.6s ease-in-out infinite}
  .coin-stack span:nth-child(2){animation-delay:-.4s}
  .coin-stack span:nth-child(3){animation-delay:-.8s}

  .castle-silhouette{position:absolute;left:50%;transform:translateX(-50%);bottom:0;width:min(56vw,720px);height:180px;opacity:.13;filter:drop-shadow(0 8px 20px rgba(0,0,0,.18));}
  .castle-silhouette::before{content:'';position:absolute;left:0;right:0;bottom:0;height:92px;background:linear-gradient(180deg,#3a6a7b,#224b5d);clip-path:polygon(0 100%,0 52%,12% 52%,12% 20%,18% 20%,18% 52%,33% 52%,33% 30%,39% 30%,39% 52%,44% 52%,44% 6%,56% 6%,56% 52%,61% 52%,61% 30%,67% 30%,67% 52%,82% 52%,82% 20%,88% 20%,88% 52%,100% 52%,100% 100%);}
  .castle-silhouette::after{content:'';position:absolute;left:28%;right:28%;bottom:0;height:110px;background:linear-gradient(180deg,#4f8397,#2e6174);clip-path:polygon(0 100%,0 42%,10% 42%,10% 0,22% 0,22% 42%,78% 42%,78% 0,90% 0,90% 42%,100% 42%,100% 100%,60% 100%,60% 68%,40% 68%,40% 100%);}

  .sparkle-group{position:absolute;inset:0}
  .sparkle-group i{position:absolute;width:9px;height:9px;border-radius:50%;background:#fff7b5;box-shadow:0 0 14px #fff176;animation:spark 2.2s ease-in-out infinite}
  .sparkle-group i:nth-child(1){left:14%;top:20%;animation-delay:-.4s}
  .sparkle-group i:nth-child(2){left:27%;top:63%;animation-delay:-1.4s}
  .sparkle-group i:nth-child(3){right:19%;top:22%;animation-delay:-.9s}
  .sparkle-group i:nth-child(4){right:31%;top:59%;animation-delay:-1.8s}
  .sparkle-group i:nth-child(5){left:50%;top:15%;animation-delay:-.2s}
  .sparkle-group i:nth-child(6){left:54%;top:72%;animation-delay:-1.1s}

  .ground-strip{position:absolute;left:0;right:0;bottom:0;height:76px;background:linear-gradient(180deg,#7ddd69,#4db644 45%,#2f8e32 100%);box-shadow:inset 0 9px 0 rgba(255,255,255,.12)}
  .ground-strip::before{content:'';position:absolute;inset:0;background:radial-gradient(circle at 10% 35%, rgba(255,255,255,.18) 0 16px, transparent 17px),radial-gradient(circle at 30% 55%, rgba(255,255,255,.12) 0 12px, transparent 13px),radial-gradient(circle at 62% 38%, rgba(255,255,255,.16) 0 14px, transparent 15px),radial-gradient(circle at 83% 58%, rgba(255,255,255,.12) 0 11px, transparent 12px)}

  .world-vignette{position:absolute;inset:0;background:radial-gradient(circle at center, transparent 55%, rgba(46,124,148,.08) 82%, rgba(0,0,0,.14) 100%);z-index:4}

  @keyframes flowerBob{0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-9px) rotate(2.5deg)}}
  @keyframes qFloat{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-10px) scale(1.04)}}
  @keyframes coinBounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}

  @media (max-width: 980px){
    .bg-flower.f3,.bg-flower.f4,.bg-qblock.qb3,.bg-qblock.qb4,.coin-stack{display:none}
    .castle-silhouette{width:min(86vw,560px);height:130px}
  }
  @media (prefers-reduced-motion:reduce){
    .bg-flower,.bg-qblock,.coin-stack span{animation:none !important}
  }

  .bg-flower,.bg-qblock{background-color:transparent !important}
  .bg-flower{filter:drop-shadow(0 14px 18px rgba(0,0,0,.18)) drop-shadow(0 0 10px rgba(255,183,0,.10)) !important}
  .bg-qblock{filter:drop-shadow(0 12px 16px rgba(0,0,0,.16)) !important}

  .parallax-back,.parallax-mid,.parallax-front,.world-vignette{pointer-events:none}
  .bg-flower,.bg-qblock{z-index:2}

  /* ===== PIECES D'OR STRICTEMENT RONDES / RELIEF METALLIQUE ===== */
  .coin-bg,
  .coin-stack span{
    position:absolute;
    width:36px !important;
    height:36px !important;
    aspect-ratio:1 / 1 !important;
    border-radius:50% !important;
    box-sizing:border-box;
    border:3px solid #a96800 !important;
    background:
      radial-gradient(circle at 32% 26%,
