  @keyframes shell-flight{0%{transform:translate(-50%,-50%) translate(0,0) scale(.82) rotate(0deg);opacity:.9}65%{opacity:1}100%{transform:translate(-50%,-50%) translate(var(--dx),var(--dy)) scale(1) rotate(var(--rot));opacity:1}}
