  .mate-close{position:absolute;right:18px;top:0;width:42px;height:42px;border:none;border-radius:50%;background:#7a3c11;color:#fff8dc;font-size:1.9rem;line-height:1;cursor:pointer;box-shadow:0 4px 0 rgba(0,0,0,.15);display:grid;place-items:center;padding:0;text-align:center;z-index:2}
