  .mate-sign{position:relative;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;min-width:min(54vw,500px);padding:26px 28px;background:linear-gradient(180deg,#fffef8 0%,#fff7db 100%);border:8px solid #8a4d15;border-radius:24px;box-shadow:0 10px 0 rgba(115,62,16,.18), inset 0 2px 0 rgba(255,255,255,.65)}
  .mate-sign:before,.mate-sign:after{content:'';position:absolute;top:-16px;width:78px;height:18px;background:#d09039;border:4px solid #8a4d15;border-bottom:none;border-radius:12px 12px 0 0}
  .mate-sign:before{left:48px} .mate-sign:after{right:48px}
  .mate-sign-top{font-size:clamp(1.8rem,4vw,3rem);font-weight:1000;line-height:1;color:#b31813;text-shadow:0 2px 0 #fff, 0 5px 0 rgba(0,0,0,.08);letter-spacing:.04em;margin-bottom:8px}
  .mate-sign-winner{font-size:clamp(1rem,2vw,1.45rem);font-weight:900;color:#6a3410;letter-spacing:.08em;margin-bottom:6px}
  .mate-sign-name{font-size:clamp(1.6rem,4vw,2.8rem);font-weight:1000;color:#1f3d1a;background:linear-gradient(180deg,#fff2a8,#ffd452);border:4px solid #7a3c11;border-radius:16px;padding:10px 18px;box-shadow:0 6px 0 rgba(122,60,17,.16)}
  .mate-replay{margin-top:18px;border:none;border-radius:16px;padding:12px 24px;background:linear-gradient(180deg,#42d85a 0%,#1ea63b 100%);color:#fffef2;font-weight:1000;font-size:clamp(1rem,2.2vw,1.35rem);letter-spacing:.03em;cursor:pointer;border:4px solid #0c6a22;box-shadow:0 6px 0 rgba(12,106,34,.24), inset 0 2px 0 rgba(255,255,255,.22);transition:transform .08s ease, filter .15s ease}
  .mate-replay:hover{filter:brightness(1.05)}
  .mate-replay:active{transform:translateY(2px);box-shadow:0 4px 0 rgba(12,106,34,.24), inset 0 2px 0 rgba(255,255,255,.22)}
  @keyframes mateFade{from{opacity:0}to{opacity:1}}
  @keyframes lakituDrop{0%{opacity:0;transform:translateY(-240px) scale(.78)}55%{opacity:1;transform:translateY(18px) scale(1.02)}72%{transform:translateY(-8px) scale(.99)}100%{opacity:1;transform:translateY(0) scale(1)}}
