  /* ===== CHRONO 10 MIN PAR CAMP ===== */
  .chess-clocks{
    position:relative;
    z-index:6;
    width:min(700px,calc(100% - 28px));
    margin:8px auto 10px;
    display:grid;
    grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);
    align-items:center;
    gap:10px;
  }
  .chess-clock{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:12px;
    min-width:0;
    padding:8px 14px;
    border:4px solid #60331a;
    border-radius:17px;
    background:linear-gradient(180deg,#fff9df,#ffe5a1);
    box-shadow:0 5px 0 rgba(92,47,19,.16),0 10px 20px rgba(0,0,0,.10);
    color:#5a2b14;
    transition:transform .18s ease,filter .18s ease,box-shadow .18s ease;
  }
  .chess-clock span{
    font-weight:1000;
    font-size:.82rem;
    letter-spacing:.06em;
  }
  .chess-clock strong{
    min-width:82px;
    text-align:center;
    font-variant-numeric:tabular-nums;
    font-size:1.6rem;
    line-height:1;
    color:#173717;
  }
  .chess-clock.active{
    transform:translateY(-2px);
    filter:brightness(1.04);
    box-shadow:0 6px 0 rgba(29,123,45,.24),0 0 0 3px rgba(49,212,84,.28),0 12px 25px rgba(0,0,0,.12);
  }
  .chess-clock.low strong{
    color:#b51c11;
    animation:clockPulse .8s ease-in-out infinite;
  }
  .chess-clock.timeout{
    background:linear-gradient(180deg,#ffd5c8,#ff9a7d);
    border-color:#8f1c11;
  }
  .clock-center{
    padding:6px 10px;
    border-radius:999px;
    border:3px solid #60331a;
    background:linear-gradient(180deg,#43d65a,#1a9e38);
    color:#fffdf0;
    font-weight:1000;
    font-size:.78rem;
    letter-spacing:.05em;
    box-shadow:0 4px 0 rgba(57,107,36,.18);
  }
  @keyframes clockPulse{
    0%,100%{transform:scale(1)}
    50%{transform:scale(1.06)}
  }
  @media (max-width:640px){
    .chess-clocks{grid-template-columns:1fr 1fr;gap:8px}
    .clock-center{display:none}
    .chess-clock{padding:8px 10px}
    .chess-clock strong{font-size:1.35rem;min-width:68px}
    .chess-clock span{font-size:.72rem}
  }


