@keyframes piece-slam-shrink{0%{opacity:1;transform:translateX(-50%) translateY(-18px) scale(1)}38%{opacity:1;transform:translateX(-50%) translateY(0) scale(1)}52%{opacity:1;transform:translateX(-50%) translateY(6px) scale(.78)}70%{opacity:.96;transform:translateX(-50%) translateY(14px) scale(.48)}100%{opacity:0;transform:translateX(-50%) translateY(28px) scale(.14)}}

