  /* =========================================================
     LOADSCREEN 0 → 100 % — v42
     ========================================================= */
  .game-loader{
    position:fixed;
    inset:0;
    z-index:50000;
    display:flex;
    align-items:center;
    justify-content:center;
    min-height:100svh;
    padding:
      max(18px,env(safe-area-inset-top))
      max(18px,env(safe-area-inset-right))
      max(18px,env(safe-area-inset-bottom))
      max(18px,env(safe-area-inset-left));
    background:
      radial-gradient(circle at 50% 38%,rgba(255,255,255,.16),transparent 26%),
      linear-gradient(180deg,#ef423c 0%,#d72424 55%,#aa1111 100%);
    opacity:1;
    visibility:visible;
    transition:opacity .38s ease,visibility .38s ease;
    overflow:hidden;
  }

  .game-loader::before,
  .game-loader::after{
    content:"";
    position:absolute;
    width:46vw;
    height:46vw;
    max-width:520px;
    max-height:520px;
    border-radius:50%;
    border:2px solid rgba(255,255,255,.07);
    pointer-events:none;
  }
  .game-loader::before{transform:translate(-53vw,-42vh)}
  .game-loader::after{transform:translate(53vw,42vh)}

  .game-loader.is-done{
    opacity:0;
    visibility:hidden;
    pointer-events:none;
  }

  .game-loader-card{
    position:relative;
    width:min(88vw,390px);
    display:flex;
    flex-direction:column;
    align-items:center;
    gap:12px;
    text-align:center;
  }

  .game-loader-icon-wrap{
    position:relative;
    width:112px;
    height:112px;
    display:grid;
    place-items:center;
  }

  .game-loader-ring{
    position:absolute;
    inset:0;
    border-radius:50%;
    border:5px solid rgba(255,255,255,.22);
    border-top-color:#fff7bb;
    border-right-color:#ffd43b;
    animation:loaderSpin 1s linear infinite;
    filter:drop-shadow(0 7px 8px rgba(83,0,0,.22));
  }

  .game-loader-icon{
    width:86px;
    height:86px;
    object-fit:contain;
    border-radius:20px;
    filter:drop-shadow(0 8px 10px rgba(69,0,0,.32));
    transform:translateZ(0);
  }

  .game-loader-title{
    color:#fff;
    font-size:clamp(1.6rem,7vw,2.2rem);
    line-height:1;
    font-weight:1000;
    letter-spacing:.02em;
    text-shadow:0 4px 0 rgba(109,9,9,.5);
  }

  .game-loader-status{
    min-height:20px;
    color:#fff7de;
    font-size:.86rem;
    font-weight:850;
  }

  .game-loader-progress-shell{
    position:relative;
    width:100%;
    height:22px;
    padding:4px;
    border:3px solid rgba(93,11,11,.7);
    border-radius:999px;
    background:rgba(86,6,6,.25);
    box-shadow:
      inset 0 2px 5px rgba(71,0,0,.35),
      0 4px 0 rgba(112,7,7,.24);
    overflow:hidden;
  }

  .game-loader-progress{
    width:0%;
    height:100%;
    border-radius:999px;
    background:
      linear-gradient(180deg,#fff47b 0%,#ffd32f 52%,#ffb10f 100%);
    box-shadow:
      inset 0 2px 0 rgba(255,255,255,.58),
      0 0 12px rgba(255,222,69,.55);
    transition:width .18s ease-out;
  }

  .game-loader-progress::after{
    content:"";
    display:block;
    height:45%;
    margin:2px 5px 0;
    border-radius:999px;
    background:rgba(255,255,255,.38);
  }

  .game-loader-percent{
    min-width:82px;
    padding:5px 10px;
    border-radius:999px;
    color:#66100d;
    background:#fff5c7;
    border:3px solid rgba(94,15,9,.62);
    font-size:1rem;
    line-height:1;
    font-weight:1000;
    font-variant-numeric:tabular-nums;
    box-shadow:0 4px 0 rgba(102,12,9,.22);
  }

  .game-loader.error .game-loader-ring{
    animation:none;
    border-color:#fff;
  }
  .game-loader.error .game-loader-progress{
    background:#fff;
  }

  @keyframes loaderSpin{
    to{transform:rotate(360deg)}
  }

  @media(max-width:430px){
    .game-loader-card{
      width:min(90vw,350px);
