    box-shadow:0 5px 0 rgba(93,38,13,.14);
    position:relative;
    z-index:5;
  }
  .elo-player,.elo-opponent{
    min-width:0;
    display:grid;
    grid-template-columns:auto auto 1fr;
    align-items:center;
    gap:7px;
  }
  .elo-opponent{text-align:right}
  .elo-opponent .elo-label{order:3}
  .elo-opponent strong{order:2}
  .elo-opponent .elo-rank{order:1;justify-self:start}
  .elo-label{
    font-size:.66rem;
    font-weight:1000;
    color:#743315;
    letter-spacing:.07em;
    white-space:nowrap;
  }
  .elo-hud strong{
