    border:2px solid rgba(94,46,15,.34);
    border-radius:999px;
    background:#fff7d2;
    color:#613113;
    font-size:.61rem;
    line-height:1;
    font-weight:1000;
    letter-spacing:.04em;
    white-space:nowrap;
    overflow:hidden;
    text-overflow:ellipsis;
  }
  .elo-versus{
    width:30px;
    height:30px;
    display:grid;
    place-items:center;
    border-radius:50%;
    background:linear-gradient(#ef443d,#bd1717);
