    font-weight:900;
  }
  .elo-result{
    margin-top:11px;
    padding:8px 13px;
    display:grid;
    grid-template-columns:auto auto;
    gap:1px 8px;
    align-items:center;
    border:3px solid #77300f;
    border-radius:14px;
    background:linear-gradient(180deg,#fff9d5,#ffdf70);
    color:#66300e;
    box-shadow:0 4px 0 rgba(110,48,12,.13);
  }
  .elo-result.hidden{display:none}
  .elo-result span{
    font-size:.72rem;
    font-weight:1000;
    letter-spacing:.07em;
  }
  .elo-result strong{
    font-size:1.28rem;
