  /* =========================================================
     PIÈCES CAPTURABLES APRÈS SÉLECTION — v55
     ========================================================= */
  .sq.capture-target{
    box-shadow:
      inset 0 0 0 4px rgba(255,55,48,.96),
      inset 0 0 20px rgba(255,55,48,.32) !important;
  }

  .sq.capture-target::after{
    content:"";
    position:absolute;
    inset:7%;
    z-index:5;
    pointer-events:none;
    border:4px solid #ff3b30;
    border-radius:50%;
    box-shadow:
      0 0 0 2px rgba(255,255,255,.75),
      0 0 15px rgba(255,59,48,.85);
    animation:captureTargetPulse .8s ease-in-out infinite;
  }

  .sq.capture-target::before{
    content:"×";
    position:absolute;
    top:3px;
    right:3px;
    z-index:7;
    width:19px;
    height:19px;
    display:grid;
    place-items:center;
    pointer-events:none;
    border:2px solid #fff;
    border-radius:50%;
    background:#e62d28;
    color:#fff;
    font-size:14px;
    line-height:1;
    font-weight:1000;
    box-shadow:0 2px 5px rgba(73,0,0,.28);
  }

  .piece.capture-threat{
    animation:captureThreatPulse .8s ease-in-out infinite;
    filter:
      drop-shadow(0 0 5px rgba(255,255,255,.95))
      drop-shadow(0 0 8px rgba(255,48,40,.95)) !important;
  }

  .dot.capture-landing{
    background:#ef3f36 !important;
    border-color:rgba(255,255,255,.92) !important;
    box-shadow:0 0 14px rgba(239,63,54,.72) !important;
  }

  @keyframes captureTargetPulse{
    0%,100%{transform:scale(.94);opacity:.72}
    50%{transform:scale(1.03);opacity:1}
  }

  @keyframes captureThreatPulse{
    0%,100%{transform:scale(1)}
    50%{transform:scale(.91)}
  }

  @media(max-width:600px){
    .sq.capture-target{
      box-shadow:
        inset 0 0 0 3px rgba(255,55,48,.97),
        inset 0 0 12px rgba(255,55,48,.30) !important;
    }
    .sq.capture-target::after{
      inset:6%;
      border-width:3px;
    }
    .sq.capture-target::before{
      top:2px;
      right:2px;
      width:15px;
      height:15px;
      border-width:1px;
      font-size:11px;
    }
  }


