  outline:none;
  text-align:center;
  text-transform:uppercase;
  font:inherit;
  font-size:.74rem;
  font-weight:900;
  letter-spacing:.08em;
  background:#fffdf6;
  user-select:text;
}
.correspondence-join-row button { min-width:105px; }
.correspondence-created {
  margin:12px 0 8px;
  padding:12px;
  border:2px solid rgba(85,64,169,.24);
  border-radius:15px;
  text-align:center;
  background:rgba(238,231,255,.72);
}
.correspondence-created span,
.correspondence-created small { display:block; color:#735e99; font-size:.58rem; font-weight:850; }
.correspondence-created strong { display:block; margin:4px 0; color:#503b8e; font-family:"Outfit","Nunito",sans-serif; font-size:1.35rem; letter-spacing:.12em; }
.correspondence-status { min-height:18px; margin:7px 0; text-align:center; color:#7c5737; font-size:.62rem; font-weight:850; }
.correspondence-status.error { color:#ae281f; }
.correspondence-status.ok { color:#24713a; }
.correspondence-status.wait { color:#6546a1; }
.correspondence-list-head { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-top:13px; padding-bottom:7px; }
.correspondence-list-head strong { color:#5f3018; font-size:.76rem; }
.correspondence-list-head button { border:0; border-radius:9px; padding:6px 9px; cursor:pointer; color:#65451f; background:rgba(255,255,255,.68); font:inherit; font-size:.56rem; font-weight:900; }
.correspondence-list { display:flex; flex-direction:column; gap:7px; }
.correspondence-game-item {
  width:100%;
  min-height:58px;
  padding:9px 10px;
  border:2px solid rgba(96,51,26,.16);
  border-radius:13px;
  cursor:pointer;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  text-align:left;
  color:#5c3018;
  background:rgba(255,255,255,.58);
  font:inherit;
}
.correspondence-game-item.active { border-color:rgba(76,129,67,.35); }
.correspondence-game-main { min-width:0; display:flex; flex-direction:column; }
.correspondence-game-main strong { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:.69rem; }
.correspondence-game-main small { margin-top:3px; color:#84603e; font-size:.56rem; font-weight:800; }
.correspondence-game-badge { flex:0 0 auto; padding:5px 7px; border-radius:8px; color:#fff; background:#6550af; font-size:.52rem; font-weight:1000; }
.correspondence-empty { padding:14px 8px; text-align:center; color:#88613e; font-size:.64rem; font-weight:800; }
.correspondence-auth-note { margin-top:14px; padding:15px; border:2px solid rgba(96,51,26,.18); border-radius:15px; text-align:center; background:rgba(255,255,255,.54); }
.correspondence-auth-note strong,.correspondence-auth-note span { display:block; }
.correspondence-auth-note strong { color:#5c3018; font-size:.78rem; }
.correspondence-auth-note span { margin:5px 0 10px; color:#805a38; font-size:.62rem; font-weight:800; }
.correspondence-auth-note button { width:100%; }

@media(max-width:760px){
  .correspondence-overlay { padding:8px 7px calc(8px + env(safe-area-inset-bottom,0px)); }
  .correspondence-sheet { padding:20px 10px 12px; border-width:3px; border-radius:22px 22px 15px 15px; }
  .correspondence-join-row { grid-template-columns:1fr; }
  .correspondence-join-row button { width:100%; }
}

