/* =========================================================
   PARTIES DIFFÉRÉES EN COURS — SIDEBAR v71
   ========================================================= */
.ongoing-games-block {
  border-bottom: 4px solid var(--panel-border);
  background: linear-gradient(180deg, rgba(246,255,235,.96), rgba(228,247,202,.92));
}

.ongoing-games-head {
  min-height: 46px;
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: #4c2a12;
  background: linear-gradient(180deg,#dff59c,#b9df6c);
  border-bottom: 2px solid rgba(75,43,18,.22);
}

.ongoing-games-head strong {
  font-family: "Outfit", "Nunito", sans-serif;
  font-size: .78rem;
  font-weight: 900;
  letter-spacing: .045em;
  text-transform: uppercase;
}

.ongoing-games-count {
  min-width: 24px;
  height: 24px;
  padding: 0 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 2px solid rgba(71,99,31,.28);
  border-radius: 999px;
  color: #31551f;
  background: rgba(255,255,255,.7);
  font-size: .65rem;
  font-weight: 1000;
  box-sizing: border-box;
}

.ongoing-games-list {
  max-height: 520px;
  padding: 9px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 9px;
  scrollbar-width: thin;
}

.ongoing-game-card {
  width: 100%;
  min-height: 0;
  margin: 0;
  padding: 7px;
  border: 2px solid rgba(82,50,24,.24);
  border-radius: 14px;
  display: grid;
  grid-template-columns: 76px minmax(0,1fr);
  gap: 8px;
  align-items: center;
  text-align: left;
  color: #4f2b16;
  background: rgba(255,255,255,.68);
  box-shadow: 0 3px 0 rgba(74,43,21,.08);
  cursor: pointer;
}

.ongoing-game-card.my-turn {
  border-color: #36a84f;
  background: linear-gradient(180deg,rgba(245,255,231,.96),rgba(224,248,203,.95));
  box-shadow: 0 3px 0 rgba(38,130,55,.12), inset 0 0 0 1px rgba(70,190,83,.2);
}

.ongoing-game-card.waiting {
  border-style: dashed;
}

.ongoing-game-card:active {
  transform: translateY(1px);
}

.ongoing-mini-board {
  width: 76px;
  aspect-ratio: 1;
  display: grid;
  grid-template-columns: repeat(8,1fr);
  grid-template-rows: repeat(8,1fr);
  overflow: hidden;
  border: 2px solid #5d3017;
  border-radius: 7px;
  background: #fff;
  box-shadow: 0 2px 0 rgba(74,43,21,.1);
}

.ongoing-mini-square {
  min-width: 0;
  min-height: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
}

.ongoing-mini-square.light { background: #f6f2da; }
.ongoing-mini-square.dark { background: #6dbd65; }

.ongoing-mini-square img {
  width: 92%;
  height: 92%;
  object-fit: contain;
  display: block;
  pointer-events: none;
}

.ongoing-game-info,
.ongoing-game-players,
.ongoing-player-row {
  min-width: 0;
  display: flex;
}

.ongoing-game-info {
  flex-direction: column;
  gap: 5px;
}

.ongoing-game-players {
  flex-direction: column;
  gap: 3px;
}

.ongoing-player-row {
  align-items: center;
  gap: 5px;
  font-size: .58rem;
  line-height: 1.1;
}

.ongoing-player-row b {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 900;
}

.ongoing-player-row.me b::after {
  content: " · toi";
  color: #2e7d3f;
  font-weight: 900;
}

.ongoing-color-dot {
  width: 9px;
  height: 9px;
  flex: 0 0 9px;
  border: 1px solid #4c2b17;
  border-radius: 50%;
  box-sizing: border-box;
}
.ongoing-color-dot.white { background: #fffef7; }
.ongoing-color-dot.black { background: #38281f; }

.ongoing-turn {
  width: fit-content;
  max-width: 100%;
  padding: 3px 6px;
  border-radius: 999px;
  color: #76502f;
  background: rgba(117,82,44,.09);
  font-size: .56rem;
  font-weight: 900;
  line-height: 1.15;
}

.ongoing-turn.mine {
  color: #176d31;
  background: rgba(54,168,79,.14);
}

.ongoing-deadline {
  color: #8a613c;
  font-size: .52rem;
  font-weight: 800;
  line-height: 1.1;
}

.ongoing-games-empty,
.ongoing-games-more {
  width: 100%;
  min-height: 44px;
  padding: 10px 8px;
  border: 0;
  border-radius: 11px;
  text-align: center;
  color: #7a5636;
  background: rgba(255,255,255,.48);
  font: inherit;
  font-size: .58rem;
  font-weight: 850;
  line-height: 1.3;
}

button.ongoing-games-empty,
.ongoing-games-more {
  cursor: pointer;
}

.ongoing-games-empty.error { color: #a02f25; }

.ongoing-games-more {
  color: #315f28;
  background: rgba(206,240,168,.62);
}

@media (max-width: 1260px) and (min-width: 901px) {
  .ongoing-games-list {
    max-height: 430px;
  }
}

@media (max-width: 900px) {
  .ongoing-games-block {
    border-bottom-width: 3px;
  }

  .ongoing-games-list {
    max-height: none;
    display: grid;
    grid-template-columns: repeat(2,minmax(0,1fr));
    gap: 8px;
  }

  .ongoing-game-card {
    grid-template-columns: 82px minmax(0,1fr);
  }

  .ongoing-mini-board {
    width: 82px;
  }

  .ongoing-games-empty,
  .ongoing-games-more {
    grid-column: 1 / -1;
  }
}

@media (max-width: 560px) {
  .ongoing-games-head {
    min-height: 40px;
    padding: 8px 10px;
  }

  .ongoing-games-list {
    grid-template-columns: minmax(0,1fr);
    padding: 8px;
  }

  .ongoing-game-card {
    grid-template-columns: 88px minmax(0,1fr);
    padding: 7px;
  }

  .ongoing-mini-board {
    width: 88px;
  }

  .ongoing-player-row {
    font-size: .62rem;
  }

  .ongoing-turn {
    font-size: .6rem;
  }

  .ongoing-deadline {
    font-size: .56rem;
  }
}


/* =========================================================
   ACTIONS DE PARTIE — ABANDON / NULLE — v72
   ========================================================= */
.game-actions{width:100%;box-sizing:border-box;display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:10px 0 0}
.game-action-btn{min-height:42px;padding:8px 13px;border:2px solid rgba(92,47,19,.28);border-radius:13px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px;font:inherit;font-family:"Outfit","Nunito",sans-serif;font-size:.72rem;font-weight:900}
.game-action-btn.draw{color:#624017;background:linear-gradient(180deg,#fff5b8,#f7d868);border-color:#a77a28}
.game-action-btn.resign{color:#fff;background:linear-gradient(180deg,#e45b47,#bb2d24);border-color:#8f241d}
.game-action-btn:not(:disabled):active{transform:translateY(1px)}
.game-action-btn:disabled{cursor:default;opacity:.58}
.game-action-icon{width:22px;height:22px;flex:0 0 22px;display:grid;place-items:center;border-radius:7px;background:rgba(255,255,255,.28);font-size:.9rem;font-weight:1000}
.game-action-status{grid-column:1/-1;min-height:0;margin:-1px 2px 0;text-align:center;color:#765338;font-size:.58rem;font-weight:850;line-height:1.2}
.game-action-status.wait{color:#9a6618}.game-action-status.ok{color:#23763d}.game-action-status.error{color:#ad2d24}
.game-action-overlay{position:fixed;inset:0;z-index:17000;display:none;align-items:center;justify-content:center;padding:18px;box-sizing:border-box;background:rgba(31,21,14,.52);backdrop-filter:blur(5px)}
.game-action-overlay.show{display:flex;animation:mateFade .18s ease}
.game-action-dialog{position:relative;width:min(420px,100%);padding:20px 18px 17px;box-sizing:border-box;border:4px solid #60331a;border-radius:22px;text-align:center;background:linear-gradient(180deg,#fff9df,#ffedbd);box-shadow:0 12px 0 rgba(92,47,19,.15),0 22px 44px rgba(0,0,0,.27)}
.game-action-dialog-close{position:absolute;top:10px;right:10px;width:32px;height:32px;padding:0;border:0;border-radius:50%;cursor:pointer;display:grid;place-items:center;color:#653114;background:rgba(255,255,255,.65);font-size:1.25rem;font-weight:900}
.game-action-dialog-icon{width:52px;height:52px;margin:0 auto 8px;display:grid;place-items:center;border:3px solid #6c3a1d;border-radius:16px;color:#633116;background:linear-gradient(180deg,#fff4ae,#f4cf58);font-family:"Outfit","Nunito",sans-serif;font-size:1.45rem;font-weight:1000}
.game-action-dialog-title{color:#5f2f16;font-family:"Outfit","Nunito",sans-serif;font-size:1.05rem;font-weight:950}
.game-action-dialog-text{margin:7px auto 15px;max-width:340px;color:#7d5536;font-size:.67rem;font-weight:800;line-height:1.4}
.game-action-dialog-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.game-action-dialog-actions button{min-height:42px;padding:8px 10px;border:2px solid rgba(94,49,25,.22);border-radius:12px;cursor:pointer;font:inherit;font-size:.64rem;font-weight:950}
.game-action-dialog-actions .secondary{color:#64391f;background:rgba(255,255,255,.7)}
.game-action-dialog-actions .primary{color:#fff;background:linear-gradient(180deg,#4fc866,#2ca94a);border-color:#26863f}
.game-action-dialog-actions .primary.danger{background:linear-gradient(180deg,#e45b47,#bb2d24);border-color:#8f241d}
@media(max-width:760px){.game-actions{gap:6px;padding-top:8px}.game-action-btn{min-height:40px;padding:7px 9px;border-radius:11px;font-size:.66rem}.game-action-overlay{padding:11px}.game-action-dialog{padding:18px 12px 14px;border-width:3px;border-radius:18px}}
@media(max-width:360px){.game-action-icon{display:none}}


